package main

import (
	"fmt"
)

func main() {
	var l, r int64
	fmt.Scan(&l, &r)

	var w, W [64]bool
	var q, Q int

	for l > 0 {
		w[q] = l%2 == 1
		l >>= 1
		q++
	}
	for r > 0 {
		W[Q] = r%2 == 1
		r >>= 1
		Q++
	}

	p := 0
	for i := Q; i >= 0; i-- {
		if w[i] != W[i] {
			p = i + 1
			break
		}
	}

	ans := (1 << p) - 1
	fmt.Print(ans)
}

