import (
	"fmt"
	"math/bits"
)

func main() {
	var l, r uint64
	fmt.Scan(&l, &r)

	xor := l ^ r
	if xor == 0 {
		fmt.Print(0)
		return
	}

	msb := 63 - bits.LeadingZeros64(xor)
	ans := (uint64(1) << (msb + 1)) - 1
	fmt.Print(ans)
}

